abbrev R05 (declaredLoad : Load) (observedLoadCalls : List Call) : Prop :=
  observedLoadCalls ≠ [] ∧
  ∀ call ∈ observedLoadCalls, call = { functionName := declaredLoad.functionName, arguments := declaredLoad.arguments }

